declare const tools: { mcp__pixellab__create_font(args: {
  // Style description of the font, e.g. 'warm orange arcade font'.
  description: string;
  // Explicit font family name; defaults to '{description} {weight}'.
  font_name?: string | null;
  // Native glyph resolution in pixels (real bitmap size per glyph). The atlas is a 10x8 grid of 80 glyphs, ROW-MAJOR, so cell i holds the i-th character of "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz.,!?:;'"-+()0123456789/%*=_$" — slice it with that order. There is no space glyph.
  glyph_px?: 8 | 12 | 16 | 24 | 32 | 64;
